use moloch_live_runtime::{fundamental_policy::review_sha256,value_surface::*};
use serde_json::{json,Value};
#[path="support/value_surface_fixture.rs"]mod support;
use support::*;
#[test]fn exact_original_artifact_hash_and_external_approval_are_required(){let bytes=artifact();let sha=sha256(&bytes);assert!(Surface::load(&bytes,&sha,&Default::default(),NOW).is_err());let s=Surface::load(&bytes,&sha,&[sha.clone()].into(),NOW).unwrap();assert!(s.is_research());assert_eq!(s.scenarios().len(),2);let mut changed=bytes.clone();changed.push(b' ');assert!(Surface::load(&changed,&sha,&[sha].into(),NOW).is_err());}
#[test]fn probabilities_clocks_duplicates_and_model_self_hash_fail_closed(){for case in ["weight","duplicate","dimension","future","expired","model","float"]{let mut v:Value=serde_json::from_slice(&artifact()).unwrap();match case{"weight"=>v["scenarios"][0]["weightPpm"]=json!(500001),"duplicate"=>v["scenarios"][1]["raceOutcomes"]=v["scenarios"][0]["raceOutcomes"].clone(),"dimension"=>v["scenarios"][1]["raceOutcomes"]=json!(["DEM"]),"future"=>v["observedAtMs"]=json!(NOW+1),"expired"=>v["expiresAtMs"]=json!(NOW),"float"=>v["calibration"]["pretendProbability"]=json!(0.5),_=>v["modelSha256"]=json!("b".repeat(64))};let b=if case=="model"{serde_json::to_vec(&v).unwrap()}else{seal(v)};let sha=sha256(&b);assert!(Surface::load(&b,&sha,&[sha.clone()].into(),NOW).is_err(),"{case}");}}
#[test]fn genuine_session_review_original_node_and_mapped_party_yield_exact_joint_moments(){let f=F::new();let s=f.bound(NOW).unwrap();assert_eq!(s.contracts().len(),5);assert_eq!(s.contracts()[0].ordinary_payout_micros,500000);assert_eq!(s.contracts()[0].expected_payout_micros,495000);assert_eq!(s.scenarios()[0].payout_micros,vec![1000000,1000000,1000000,1000000,0]);assert_eq!(s.moments().mean_numerators[0],500000000000);assert_eq!(s.moments().covariance_numerators[0][0],250000000000000000000000i128);assert_eq!(s.moments().covariance_numerators[0][4],-250000000000000000000000i128);assert_eq!(s.horizon_ms(),300000);assert_eq!(s.valid_until_ms(),NOW+10000);s.validate_current(&f.bank,&f.scope,NOW).unwrap();}
#[test]fn mapping_cannot_self_approve_change_race_or_reuse_other_model_source(){let mut f=F::new();f.mappings[0].party=RaceOutcome::Rep;assert!(f.bound(NOW).is_err());f.trusted_mappings.insert(mapping_sha256(&f.mappings[0]).unwrap());assert!(f.bound(NOW).is_ok(),"same .5 probability is valid only under a new explicit mapping approval");f.mappings[0].race_id="missing".into();f.trusted_mappings.insert(mapping_sha256(&f.mappings[0]).unwrap());assert!(f.bound(NOW).is_err());}
#[test]fn exact_review_probability_and_current_node_are_bound_beyond_title(){let mut f=F::new();f.receipts[0].data["root"]["contract_details"]["winnerName"]=json!("Republican Party");assert!(f.bound(NOW).is_err());f.receipts[0].data=serde_json::from_slice(&f.originals[0][2]).unwrap();f.reviews[0].ordinary_probability="0.600000".into();f.trusted_reviews.insert(review_sha256(&f.reviews[0]).unwrap());f.mappings[0].review_sha256=review_sha256(&f.reviews[0]).unwrap();f.trusted_mappings.insert(mapping_sha256(&f.mappings[0]).unwrap());assert!(f.bound(NOW).is_err());}
#[test]fn unchanged_node_cannot_refresh_stale_native_book_or_frozen_boundary(){let mut f=F::new();let s=f.bound(NOW).unwrap();assert!(s.validate_current(&f.bank,&f.scope,NOW+10000).is_err());assert!(f.bound(NOW+10001).is_err());f.book(0,NOW+1,"0.490000","0.510000",20);assert!(s.validate_current(&f.bank,&f.scope,NOW+1).is_err());}
#[test]fn terminal_probability_is_never_a_deadline_liquidation_value(){let mut f=F::new();f.reviews[0].valuation_objective=None;f.reviews[0].version=1;f.trusted_reviews.insert(review_sha256(&f.reviews[0]).unwrap());f.mappings[0].review_sha256=review_sha256(&f.reviews[0]).unwrap();f.trusted_mappings.insert(mapping_sha256(&f.mappings[0]).unwrap());assert!(f.bound(NOW).is_err());}
#[test]fn actual_fitted_atlas_artifact_parses_at_original_clock_but_remains_expired_research_now(){
 let bytes=include_bytes!("../../../research/atlas_model/atlas-research-20261016.json");let sha=sha256(bytes);let raw:Value=serde_json::from_slice(bytes).unwrap();let at=raw["observedAtMs"].as_u64().unwrap();let s=Surface::load(bytes,&sha,&[sha.clone()].into(),at).unwrap();assert_eq!(s.model_sha256(),"7db269bf1421722bf51db757f19e2bf119c60325ee93cd3e9e427792472e265c");assert_eq!(s.races().len(),5);assert_eq!(s.scenarios().len(),32);assert!(s.is_research());assert_eq!(s.scenarios().iter().map(|s|u64::from(s.weight_ppm)).sum::<u64>(),1000000);assert!(Surface::load(bytes,&sha,&[sha.clone()].into(),NOW).is_err(),"original Oct5/6 source clocks cannot be renewed by reading the file today");
}
